import{_ as a}from"./chunks/rmlui.IQCB0h4b.js";import{_ as r,o as e,c as d,a2 as i}from"./chunks/framework.Ky-Ipuyb.js";const c=JSON.parse('{"title":"RmlUi 가이드","description":"","frontmatter":{"lang":"ko","sourcePath":"docs/rmlui/README.ko.md"},"headers":[],"relativePath":"ko/rmlui/index.md","filePath":"ko/rmlui/index.md"}'),l={name:"ko/rmlui/index.md"};function o(s,t,h,n,m,u){return e(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="rmlui-가이드" tabindex="-1">RmlUi 가이드 <a class="header-anchor" href="#rmlui-가이드" aria-label="Permalink to &quot;RmlUi 가이드&quot;">​</a></h1><p><a class="library-brand" href="https://mikke89.github.io/RmlUiDoc/"><img src="'+a+`" width="246" height="84" alt="RmlUi"></a></p><p><code>sfml.js-rmlui</code>로 SFML 창 안에 문서 기반 UI를 만듭니다. RML은 요소 트리, RCSS는 외형을 정의하고 JavaScript는 애플리케이션 상태와 이벤트 처리를 관리합니다. 현재 소스는 RmlUi 6.3과 SFML 3.1을 대상으로 합니다.</p><p>JavaScript와 <a href="/ko/guide/window">SFML 창</a>의 기초 지식을 전제로 합니다. RmlUi 6.3은 HTML/CSS와 비슷하지만 브라우저를 내장하지 않습니다. <a href="/ko/rmlui/data-models">네이티브 데이터 모델</a>은 스칼라와 콜백, 재귀 레코드 및 배열, 사용자 정의 변수, 공유 숫자 저장소와 부분 업데이트를 다룹니다. 아래 가이드는 런타임, 문서 트리, 스타일, 렌더링, 입력, 글꼴, 스크립트 및 리소스 소유권을 설명하며 <a href="/ko/reference/rmlui/" target="_self">API 참조</a>는 TypeScript 계약을 설명합니다.</p><h2 id="rmlui란" tabindex="-1">RmlUi란 <a class="header-anchor" href="#rmlui란" aria-label="Permalink to &quot;RmlUi란&quot;">​</a></h2><p><a href="https://github.com/mikke89/RmlUi" target="_blank" rel="noreferrer">RmlUi</a>는 HTML/CSS와 비슷한 문서 문법을 사용하는 C++ UI 라이브러리입니다. RML 문서를 한 번 로드해 지속적인 요소 트리를 만들고 RCSS로 꾸민 뒤, 애플리케이션 상태에 따라 개별 요소를 갱신합니다. RmlUi가 레이아웃과 지오메트리 생성을 담당하고 이 패키지가 SFML로 렌더링합니다.</p><p>게임 메뉴, HUD, 인벤토리 창, 레이아웃과 디자인을 별도 리소스 파일로 관리하는 UI에 적합합니다. RML, RCSS, Node.js 이벤트 처리 코드가 함께 동작하며 브라우저 DOM이나 웹 JavaScript 환경은 사용하지 않습니다. 매 프레임 위젯 호출로 도구를 구성하려면 <a href="/ko/imgui/">ImGui 가이드</a>를 참고하세요.</p><p><a href="https://mikke89.github.io/RmlUiDoc/" target="_blank" rel="noreferrer">공식 문서</a> · <a href="https://github.com/mikke89/RmlUi" target="_blank" rel="noreferrer">공식 저장소</a></p><h2 id="가이드-목록" tabindex="-1">가이드 목록 <a class="header-anchor" href="#가이드-목록" aria-label="Permalink to &quot;가이드 목록&quot;">​</a></h2><h3 id="시작하기와-문서" tabindex="-1">시작하기와 문서 <a class="header-anchor" href="#시작하기와-문서" aria-label="Permalink to &quot;시작하기와 문서&quot;">​</a></h3><table tabindex="0"><thead><tr><th>장</th><th>내용</th></tr></thead><tbody><tr><td><a href="/ko/rmlui/getting-started">빠른 시작</a></td><td>카운터 실행, 초기화, 글꼴, 프레임 순서</td></tr><tr><td><a href="/ko/rmlui/rml-rcss">RML과 RCSS 기초</a></td><td>마크업, 선택자, 레이아웃, 클릭 연결, 공식 문법 참고</td></tr><tr><td><a href="/ko/rmlui/documents">문서와 이벤트</a></td><td>RML 로드, 요소 편집, 리스너 등록, 네이티브 객체 해제</td></tr><tr><td><a href="/ko/rmlui/streams">바이트 스트림</a></td><td>파일, 메모리, 콜백 스트림 읽기와 수명</td></tr><tr><td><a href="/ko/rmlui/strings">문자열과 리소스 URL</a></td><td>문자열 처리, 리소스 경로와 URL</td></tr></tbody></table><h3 id="요소-레이아웃과-컨트롤" tabindex="-1">요소, 레이아웃과 컨트롤 <a class="header-anchor" href="#요소-레이아웃과-컨트롤" aria-label="Permalink to &quot;요소, 레이아웃과 컨트롤&quot;">​</a></h3><table tabindex="0"><thead><tr><th>장</th><th>내용</th></tr></thead><tbody><tr><td><a href="/ko/rmlui/element-state">요소 클래스, 속성과 포커스</a></td><td>요소 상태, 클래스와 포커스 변경</td></tr><tr><td><a href="/ko/rmlui/element-utilities">요소 유틸리티</a></td><td>위치 지정, 텍스트 측정, 투영 경계와 클리핑 지오메트리</td></tr><tr><td><a href="/ko/rmlui/layout">레이아웃, 스크롤과 투영</a></td><td>레이아웃 크기, 스크롤 위치와 좌표 투영</td></tr><tr><td><a href="/ko/rmlui/boxes">박스와 렌더 박스</a></td><td>박스 모델 값과 렌더 박스</td></tr><tr><td><a href="/ko/rmlui/controls">폼 컨트롤</a></td><td>입력, 선택 컨트롤과 폼 작업</td></tr><tr><td><a href="/ko/rmlui/text-panels">텍스트, 진행률 표시줄과 탭</a></td><td>텍스트 요소, 진행률 표시와 탭</td></tr><tr><td><a href="/ko/rmlui/vector-elements">SVG와 Lottie</a></td><td>네이티브 벡터 요소, 데코레이터, 프레임과 소스</td></tr><tr><td><a href="/ko/rmlui/rtti-default-actions">네이티브 타입과 기본 동작</a></td><td>요소 타입 확인과 기본 이벤트 동작</td></tr></tbody></table><h3 id="스타일-애니메이션과-렌더링" tabindex="-1">스타일, 애니메이션과 렌더링 <a class="header-anchor" href="#스타일-애니메이션과-렌더링" aria-label="Permalink to &quot;스타일, 애니메이션과 렌더링&quot;">​</a></h3><table tabindex="0"><thead><tr><th>장</th><th>내용</th></tr></thead><tbody><tr><td><a href="/ko/rmlui/numeric-values">수치와 단위</a></td><td>타입이 있는 수치, 단위와 변환</td></tr><tr><td><a href="/ko/rmlui/properties">타입 속성</a></td><td>속성 정의, 파싱과 타입 값</td></tr><tr><td><a href="/ko/rmlui/animation">애니메이션과 이징</a></td><td>요소 애니메이션, 키프레임과 이징</td></tr><tr><td><a href="/ko/rmlui/geometry-utilities">지오메트리와 합성곱</a></td><td>메시 일괄 생성과 공유 알파 버퍼 필터</td></tr><tr><td><a href="/ko/rmlui/resources">렌더링 리소스</a></td><td>텍스처, 셰이더, 필터와 Factory 리소스</td></tr><tr><td><a href="/ko/rmlui/render-state">렌더 상태</a></td><td>클리핑, 레이어, 콜백 텍스처와 상태 복원</td></tr><tr><td><a href="/ko/rmlui/rendering">렌더링과 Retina</a></td><td>SFML 합성, 고밀도 표시, 효과 지원 범위</td></tr></tbody></table><h3 id="런타임과-확장" tabindex="-1">런타임과 확장 <a class="header-anchor" href="#런타임과-확장" aria-label="Permalink to &quot;런타임과 확장&quot;">​</a></h3><table tabindex="0"><thead><tr><th>장</th><th>내용</th></tr></thead><tbody><tr><td><a href="/ko/rmlui/plugins">플러그인</a></td><td>플러그인 등록과 런타임 콜백</td></tr><tr><td><a href="/ko/rmlui/scripts">문서 스크립트</a></td><td>Node.js와 Lua 문서 스크립트</td></tr><tr><td><a href="/ko/rmlui/data-models">네이티브 데이터 모델</a></td><td>바인딩, 표현식, 공유 배열과 부분 업데이트</td></tr><tr><td><a href="/ko/rmlui/fonts">글꼴</a></td><td>글꼴 엔진, 셰이핑과 글리프 아틀라스</td></tr><tr><td><a href="/ko/rmlui/debugger">네이티브 Debugger</a></td><td>별도 호스트에서 요소, 로그, 데이터 모델 검사</td></tr><tr><td><a href="/ko/rmlui/performance">공유 저장소와 배치 처리</a></td><td>수치 명령 제출, JS 계산 배치와 리소스 준비</td></tr><tr><td><a href="/ko/rmlui/source-layout">소스 구성</a></td><td>Native 바인딩, TypeScript 인터페이스와 도구 위치</td></tr><tr><td><a href="/ko/rmlui/api">API 가이드</a></td><td>타입, 기본값, 반환값, 수명 계약 찾기</td></tr></tbody></table><p>가이드와 소스에서 생성한 API 레퍼런스는 영어, 중국어 간체, 일본어, 한국어로 유지합니다.</p><h2 id="예제-실행" tabindex="-1">예제 실행 <a class="header-anchor" href="#예제-실행" aria-label="Permalink to &quot;예제 실행&quot;">​</a></h2><p>monorepo 루트에서 실행합니다.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/bootstrap.cjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/sfml.js-rmlui/examples/demo.cjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/sfml.js-rmlui/examples/official.cjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> variables</span></span></code></pre></div><p><a href="/ko/examples/rmlui">예제 목록</a>에 스크린샷, 조작법, 소스 링크가 있습니다. 카운터의 Increment는 동작하며 variables의 미션 버튼은 호버 스타일만 보여 줍니다.</p><h2 id="소유권-경계" tabindex="-1">소유권 경계 <a class="header-anchor" href="#소유권-경계" aria-label="Permalink to &quot;소유권 경계&quot;">​</a></h2><p>프로세스 런타임은 <code>RenderWindow</code> 하나에 연결되며 초기화한 Node.js 환경과 스레드에 속합니다. 컨텍스트, 문서, 글꼴, 렌더링 리소스를 관리합니다. 래퍼는 네이티브 유효성을 공유합니다. JS 참조는 소유권이 있는 분리 트리를 유지하고 연결된 요소의 수명은 부모가 관리합니다. 파괴 시 리스너를 자동 해제하며 무효한 래퍼에 접근하면 예외가 발생합니다. SFML 창을 닫기 전에 RmlUi를 종료하세요. 지연 파괴와 Worker 제한은 <a href="/ko/rmlui/documents#네이티브-수명">네이티브 수명</a>을 참고하세요.</p>`,24)])])}const f=r(l,[["render",o]]);export{c as __pageData,f as default};
